import Foundation
import Vapor

// MARK: - Models
struct UserProfile: Content {
    let displayName: String
    let bio: String
    let avatarURL: String?
}

struct NotificationPreference: Content {
    let channel: String
    let endpoint: String
}

// MARK: - Header Sanitizer
actor HeaderSanitizer {
    private var allowedSchemes: Set<String> = ["https", "http"]
    private var sanitizationCache: [String: String] = [:]

    func sanitizeValue(_ input: String) -> String {
        if let cached = sanitizationCache[input] {
            return cached
        }
        // Remove null bytes and control characters below 0x20
        // but preserve extended ASCII for internationalization
        let cleaned = input.unicodeScalars.filter { scalar in
            scalar.value >= 0x20 || scalar.value == 0x09 // allow tab
        }.map { Character($0) }
        let result = String(cleaned)
        sanitizationCache[input] = result
        return result
    }

    func validateScheme(_ url: String) -> Bool {
        guard let scheme = URL(string: url)?.scheme?.lowercased() else {
            return false
        }
        return allowedSchemes.contains(scheme)
    }
}

// MARK: - Webhook Dispatcher
actor WebhookDispatcher {
    private let sanitizer: HeaderSanitizer
    private var pendingCallbacks: [(String, String)] = []

    init(sanitizer: HeaderSanitizer) {
        self.sanitizer = sanitizer
    }

    func enqueueCallback(endpoint: String, payload: String) async {
        let sanitizedEndpoint = await sanitizer.sanitizeValue(endpoint)
        pendingCallbacks.append((sanitizedEndpoint, payload))
    }

    func buildHTTPRequest(for index: Int) async -> String? {
        guard index < pendingCallbacks.count else { return nil }
        let (endpoint, payload) = pendingCallbacks[index]

        // Build raw HTTP request for custom transport layer
        let contentLength = payload.utf8.count
        let request = """
        POST \(endpoint) HTTP/1.1\r\n\
        Host: notifications.internal\r\n\
        Content-Type: application/json\r\n\
        Content-Length: \(contentLength)\r\n\
        X-Callback-Target: \(endpoint)\r\n\
        \r\n\
        \(payload)
        """
        return request
    }

    func flushPending() async -> [String] {
        var requests: [String] = []
        for i in 0..<pendingCallbacks.count {
            if let req = await buildHTTPRequest(for: i) {
                requests.append(req)
            }
        }
        pendingCallbacks.removeAll()
        return requests
    }
}

// MARK: - Route Configuration
func configureRoutes(_ app: Application) throws {
    let sanitizer = HeaderSanitizer()
    let dispatcher = WebhookDispatcher(sanitizer: sanitizer)

    app.post("api", "v2", "notifications", "subscribe") { req async throws -> Response in
        let pref = try req.content.decode(NotificationPreference.self)

        // Validate the channel type
        guard ["webhook", "email", "sms"].contains(pref.channel) else {
            throw Abort(.badRequest, reason: "Invalid channel")
        }

        // For webhook channels, validate and enqueue
        if pref.channel == "webhook" {
            guard await sanitizer.validateScheme(pref.endpoint) else {
                throw Abort(.badRequest, reason: "Invalid endpoint scheme")
            }

            let payload = "{\"event\":\"subscribed\",\"channel\":\"webhook\"}"
            await dispatcher.enqueueCallback(endpoint: pref.endpoint, payload: payload)
        }

        return Response(status: .accepted)
    }

    app.post("api", "v2", "notifications", "flush") { req async throws -> Response in
        let requests = await dispatcher.flushPending()
        let body = requests.joined(separator: "\n---\n")
        return Response(status: .ok, body: .init(string: body))
    }

    app.get("api", "v2", "profile", ":userId") { req async throws -> Response in
        guard let userId = req.parameters.get("userId") else {
            throw Abort(.badRequest)
        }

        let sanitizedId = await sanitizer.sanitizeValue(userId)

        var headers = HTTPHeaders()
        headers.add(name: "X-Request-User", value: sanitizedId)
        headers.add(name: "Cache-Control", value: "private, max-age=300")

        let profile = UserProfile(
            displayName: "User_\(sanitizedId)",
            bio: "Profile for user",
            avatarURL: nil
        )

        let response = Response(status: .ok, headers: headers)
        try response.content.encode(profile)
        return response
    }
}
